//! The command reference: usage and description of every Tcl command.
//!
//! One table feeds `help`, `usage` and `server/docs/commands.md` (generated by the test
//! `help::tests::reference_is_up_to_date`; `UPDATE_DOCS=1 cargo test -p aurix-core reference`
//! writes it). A test fails when a registered command has no entry here, so a new command cannot
//! ship undocumented.
//!
//! Commands a cfg script defines can document themselves with OpenOCD's `add_help_text` and
//! `add_usage_text`; `help` lists them with the built-in ones.

use std::collections::BTreeMap;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Section {
    Config,
    Adapter,
    Targets,
    TargetObject,
    Reset,
    Run,
    Memory,
    Breakpoints,
    Core,
    Flash,
    Server,
    Script,
    TasClient,
    Winidea,
    Bluebox,
    Compat,
}

impl Section {
    pub const ALL: &'static [Section] = &[
        Section::Config,
        Section::Adapter,
        Section::Targets,
        Section::TargetObject,
        Section::Reset,
        Section::Run,
        Section::Memory,
        Section::Breakpoints,
        Section::Core,
        Section::Flash,
        Section::Server,
        Section::Script,
        Section::TasClient,
        Section::Winidea,
        Section::Bluebox,
        Section::Compat,
    ];

    pub fn title(self) -> &'static str {
        match self {
            Section::Config => "Session setup",
            Section::Adapter => "Probe (adapter)",
            Section::Targets => "Taps and targets",
            Section::TargetObject => "Target objects (`<target> ...`)",
            Section::Reset => "Reset",
            Section::Run => "Run control",
            Section::Memory => "Memory and registers",
            Section::Breakpoints => "Breakpoints and watchpoints",
            Section::Core => "Core-specific (`tricore`, `cortex_m`, `gtm_mcs`, `xc800`)",
            Section::Flash => "Flash",
            Section::Server => "Server, ports and logging",
            Section::Script => "Scripting",
            Section::TasClient => "TAS adapter (`adapter driver tas_client`)",
            Section::Winidea => "winIDEA adapter (`adapter driver winidea`)",
            Section::Bluebox => "BlueBox adapter (`adapter driver bluebox`)",
            Section::Compat => "Accepted for OpenOCD compatibility",
        }
    }
}

/// One command or subcommand.
pub struct Entry {
    /// The command words, e.g. `reset_config`, `adapter speed`, `<target> configure`.
    pub name: &'static str,
    /// The arguments after the name (OpenOCD notation: `<value>`, `[optional]`, `a|b`).
    pub usage: &'static str,
    /// One line, shown by `help` in lists.
    pub summary: &'static str,
    /// The rest, shown by `help <command>` and in the reference. May be empty.
    pub details: &'static str,
    pub section: Section,
}

macro_rules! e {
    ($section:ident, $name:literal, $usage:literal, $summary:literal) => {
        e!($section, $name, $usage, $summary, "")
    };
    ($section:ident, $name:literal, $usage:literal, $summary:literal, $details:expr) => {
        Entry { name: $name, usage: $usage, summary: $summary, details: $details, section: Section::$section }
    };
}

