/// Help a cfg script added with `add_help_text` / `add_usage_text`.
#[derive(Clone, Debug, Default)]
pub struct UserHelp {
    pub usage: String,
    pub help: String,
}

/// What `help` and `usage` show: the table plus what scripts added.
struct Shown<'a> {
    name: &'a str,
    usage: &'a str,
    summary: &'a str,
    details: &'a str,
}

fn all<'a>(user: &'a BTreeMap<String, UserHelp>) -> Vec<Shown<'a>> {
    let mut out: Vec<Shown> = ENTRIES
        .iter()
        .map(|e| Shown { name: e.name, usage: e.usage, summary: e.summary, details: e.details })
        .collect();
    for (name, h) in user {
        // A script may document a built-in command again; its text wins.
        out.retain(|s| s.name != name);
        let (summary, details) = h.help.split_once('\n').unwrap_or((&h.help, ""));
        out.push(Shown { name, usage: &h.usage, summary, details });
    }
    out
}

fn line(s: &Shown) -> String {
    if s.usage.is_empty() {
        s.name.to_string()
    } else {
        format!("{} {}", s.name, s.usage)
    }
}

fn full(s: &Shown) -> String {
    let mut out = format!("{}\n    {}", line(s), s.summary);
    for l in s.details.lines() {
        out.push_str("\n    ");
        out.push_str(l);
    }
    out
}

/// `help [words...]`. `targets` are the target names, so `help cpu0` shows the `<target>` commands.
pub fn help(args: &[&str], user: &BTreeMap<String, UserHelp>, targets: &[String]) -> String {
    let shown = all(user);
    if args.is_empty() {
        let mut out = vec!["Commands (`help <command>` for details, `help <word>` to search):".to_string()];
        let width = shown.iter().map(|s| s.name.len()).max().unwrap_or(0).min(32);
        let row = |s: &Shown| format!("  {:width$}  {}", s.name, s.summary);
        for section in Section::ALL {
            let names: Vec<&str> = ENTRIES.iter().filter(|e| e.section == *section).map(|e| e.name).collect();
            let mine: Vec<String> = shown.iter().filter(|s| names.contains(&s.name) && !user.contains_key(s.name)).map(row).collect();
            if !mine.is_empty() {
                out.push(format!("\n{}", section.title().replace('`', "")));
                out.extend(mine);
            }
        }
        if !user.is_empty() {
            out.push("\nDocumented by the cfg scripts".into());
            out.extend(shown.iter().filter(|s| user.contains_key(s.name)).map(row));
        }
        return out.join("\n");
    }
    // `help cpu0 ...` is about the `<target> ...` commands.
    let mut words: Vec<&str> = args.to_vec();
    if targets.iter().any(|t| t == words[0]) {
        words[0] = "<target>";
    }
    let query = words.join(" ");
    // The command itself and its subcommands, `adapter` -> `adapter driver`, `adapter speed`, ...
    let named: Vec<&Shown> =
        shown.iter().filter(|s| s.name == query || s.name.starts_with(&format!("{query} "))).collect();
    if !named.is_empty() {
        return named.iter().map(|s| full(s)).collect::<Vec<_>>().join("\n\n");
    }
    let q = query.to_lowercase();
    let found: Vec<&Shown> = shown
        .iter()
        // `help` itself is left out: its examples would match every search for them.
        .filter(|s| s.name != "help")
        .filter(|s| [s.name, s.usage, s.summary, s.details].iter().any(|t| t.to_lowercase().contains(&q)))
        .collect();
    match found.len() {
        0 => format!("no command matches '{query}' (`help` lists them all)"),
        1 => full(found[0]),
        _ => {
            let mut out = vec![format!("commands mentioning '{query}' (`help <command>` for details):")];
            out.extend(found.iter().map(|s| format!("  {}  {}", s.name, s.summary)));
            out.join("\n")
        }
    }
}

/// `usage [words...]`.
pub fn usage(args: &[&str], user: &BTreeMap<String, UserHelp>) -> String {
    let shown = all(user);
    let query = args.join(" ");
    let hits: Vec<String> = shown
        .iter()
        .filter(|s| query.is_empty() || s.name == query || s.name.starts_with(&format!("{query} ")))
        .map(line)
        .collect();
    if hits.is_empty() {
        format!("no command '{query}' (`help {query}` searches the descriptions)")
    } else {
        hits.join("\n")
    }
}

/// `server/docs/commands.md`.
pub fn markdown() -> String {
    let mut out = String::from(
        "# Tcl command reference\n\n\
         <!-- Generated from crates/core/src/help.rs by `UPDATE_DOCS=1 cargo test -p aurix-core reference`. Do not edit. -->\n\n\
         The commands aurix-dbg understands in cfg scripts, on the Tcl console (`telnet localhost 4444`), as `monitor` \
         commands in the VS Code Debug Console or GDB, in `configCommands` and in debugger actions. They follow OpenOCD \
         where OpenOCD has the same command.\n\n\
         The same text is available at runtime: `help` lists the commands, `help <command>` describes one and its \
         subcommands, and `help <word>` searches the descriptions (`monitor help srst`). `usage <command>` shows only \
         the arguments. Procs of cfg scripts appear there too when the script documents them with `add_help_text` and \
         `add_usage_text`.\n\n\
         Notation: `<value>` is a value to fill in, `[...]` is optional, `a|b` is one of the choices.\n\n",
    );
    out.push_str("## Contents\n\n");
    for section in Section::ALL {
        out.push_str(&format!("- [{}](#{})\n", section.title(), anchor(section.title())));
    }
    for section in Section::ALL {
        out.push_str(&format!("\n## {}\n", section.title()));
        for e in ENTRIES.iter().filter(|e| e.section == *section) {
            out.push_str(&format!("\n### `{}`\n\n", e.name));
            if e.usage.is_empty() {
                out.push_str(&format!("```\n{}\n```\n\n", e.name));
            } else {
                out.push_str(&format!("```\n{} {}\n```\n\n", e.name, e.usage));
            }
            out.push_str(e.summary);
            out.push('\n');
            if !e.details.is_empty() {
                out.push('\n');
                out.push_str(e.details);
                out.push('\n');
            }
        }
    }
    out
}

/// GitHub's heading anchors: lower case, spaces to `-`, punctuation dropped.
fn anchor(title: &str) -> String {
    title
        .to_lowercase()
        .chars()
        .filter_map(|c| match c {
            ' ' => Some('-'),
            c if c.is_alphanumeric() || c == '-' || c == '_' => Some(c),
            _ => None,
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    fn commands(interp: &jim::Interp) -> HashSet<String> {
        interp.eval("info commands").unwrap().split_whitespace().map(str::to_string).collect()
    }

    /// Every command the server registers has an entry, and every entry names a real command.
    #[test]
    fn every_command_is_documented() {
        let builtins = commands(&jim::Interp::new());
        let s = crate::Server::new();
        let ours: HashSet<String> =
            commands(&s.interp).difference(&builtins).filter(|c| !c.starts_with('_')).cloned().collect();
        assert!(ours.contains("reset_config") && ours.contains("write_memory") && ours.len() > 60, "{ours:?}");
        let documented: HashSet<&str> =
            ENTRIES.iter().map(|e| e.name.split(' ').next().unwrap()).filter(|w| *w != "<target>").collect();
        let missing: Vec<&String> = ours.iter().filter(|c| !documented.contains(c.as_str())).collect();
        assert!(missing.is_empty(), "commands without an entry in help::ENTRIES: {missing:?}");
        let gated = ["winidea", "bluebox"];
        let stale: Vec<&&str> =
            documented.iter().filter(|w| !ours.contains(**w) && !gated.contains(*w)).collect();
        assert!(stale.is_empty(), "help::ENTRIES documents commands that do not exist: {stale:?}");
    }

    #[test]
    fn reference_is_up_to_date() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs/commands.md");
        let want = markdown();
        if std::env::var_os("UPDATE_DOCS").is_some() {
            std::fs::write(&path, &want).unwrap();
            return;
        }
        let have = std::fs::read_to_string(&path).unwrap_or_default().replace("\r\n", "\n");
        assert!(
            have == want,
            "server/docs/commands.md is out of date: run `UPDATE_DOCS=1 cargo test -p aurix-core reference`"
        );
    }

    #[test]
    fn help_finds_commands() {
        let none = BTreeMap::new();
        let targets = vec!["cpu0".to_string()];
        assert!(help(&["reset_config"], &none, &targets).contains("connect_assert_srst"));
        assert!(help(&["srst"], &none, &targets).contains("reset_config"));
        assert!(help(&["adapter"], &none, &targets).contains("adapter debug_password"));
        assert!(help(&["cpu0"], &none, &targets).contains("<target> configure"));
        assert!(help(&["cpu0", "arp_halt"], &none, &targets).contains("Request a halt"));
        assert!(help(&[], &none, &targets).contains("reset_config"));
        assert_eq!(usage(&["bp"], &none), "bp [<address> <length> ['hw']]");

        let mut user = BTreeMap::new();
        user.insert("sbc_status".to_string(), UserHelp { usage: String::new(), help: "Show the FS26 state.".into() });
        assert!(help(&[], &user, &targets).contains("sbc_status"));
        assert!(help(&["fs26"], &user, &targets).contains("Show the FS26 state."));
    }
}
